import{_ as t,C as r,o as l,c as i,j as p,a as o,E as n,a6 as s}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"为什么“自助”正在毁掉你的生活","description":"","frontmatter":{"title":"为什么“自助”正在毁掉你的生活","originalTitle":"Why Self-Help Is Ruining Your Life","date":"2021-05-12","originalUrl":"https://thedankoe.com/letters/why-self-help-is-ruining-your-life/","minutes":4,"sourceHash":"c4bba821b0704af6384d2ebbf7b52014d018d5a8f49a2d728f06ef8df71e06f2","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/why-self-help-is-ruining-your-life/"}]]},"headers":[],"relativePath":"letters/why-self-help-is-ruining-your-life.md","filePath":"letters/why-self-help-is-ruining-your-life.md"}'),h={name:"letters/why-self-help-is-ruining-your-life.md"};function d(f,e,u,c,m,b){const a=r("ArticleMeta");return l(),i("div",null,[e[0]||(e[0]=p("h1",{id:"为什么-自助-正在毁掉你的生活",tabindex:"-1"},[o("为什么“自助”正在毁掉你的生活 "),p("a",{class:"header-anchor",href:"#为什么-自助-正在毁掉你的生活","aria-label":'Permalink to "为什么“自助”正在毁掉你的生活"'},"​")],-1)),n(a),e[1]||(e[1]=s('<p>自助（Self-help）正在让你感到痛苦。让我们改变这一点。</p><p>这是我最近一直在思考的话题。我想先开宗明义地声明一点：自助本身并不坏。在很多情况下，它甚至大有裨益。</p><p>但你从阅读自助内容中获得的能量和信息需要被正确地引导。</p><p><a href="https://www.youtube.com/embed/Ms6cMzHVEvA?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><h2 id="自助的问题所在" tabindex="-1">自助的问题所在 <a class="header-anchor" href="#自助的问题所在" aria-label="Permalink to &quot;自助的问题所在&quot;">​</a></h2><p>你是否曾买过一本书，并满心期待它能改变你的生活？别撒谎。</p><p>书的标题、副标题以及外界的赞誉勾住了我们的注意力。我们在脑海中建立了虚假的期望，满怀激动地下单买书，然后开始消化它。</p><p>但问题是……你我都很清楚，单靠阅读是无法改变你的生活的。</p><p>我们最终陷入了一个循环：本带着良好的初衷去阅读，结果却变成了仅仅为了自我感觉良好而阅读。</p><p>这被称为精神自慰。</p><p>阅读关于提升自我的内容，却并没有真正去提升自己。</p><p>阅读仅仅是为了自我感觉良好，为了觉得自己好像真的一直在进步。</p><p>实际上，你的大脑喜欢收集那些多巴胺带来的快感，并进一步强化这种精神自慰的循环。</p><h2 id="自助与自我提升的区别" tabindex="-1">自助与自我提升的区别 <a class="header-anchor" href="#自助与自我提升的区别" aria-label="Permalink to &quot;自助与自我提升的区别&quot;">​</a></h2><p>自助是外在动力——依靠外部因素来激励你。</p><p>对于世界上像大卫·戈金斯（David Goggins）那样的人来说（“去他妈的动力，你需要的只有自律”），你现在应该能看出问题出在哪了。</p><p>“你需要的只有自律”，这部分是正确的。</p><p>我们从自助书籍中获得的外在动力之所以有用，有三个原因：</p><ul><li>我们受到了激励（这可以作为进入自律状态的初始动力）</li><li>我们掌握了一个可以改变我们生活的概念</li><li>我们知道如何去践行这个概念</li></ul><p>奇迹往往发生在最后一点上。它构成了自我提升的基础。</p><p>这就是两者之间的区别。</p><p>自助 = 不可持续的动力</p><p>自我提升 = 践行自助概念，看到结果，并培养内在动力</p><h2 id="会他妈毁了你的事" tabindex="-1">会他妈毁了你的事 <a class="header-anchor" href="#会他妈毁了你的事" aria-label="Permalink to &quot;会他妈毁了你的事&quot;">​</a></h2><p>并非所有的自我提升方式都一样有效。</p><p>许多人无法理解的是，<em>某些</em>概念可能对你根本不起作用。我们是人类，每个人都有自己独特的一面。</p><p>这就是导致“反自我提升”心态的原因。</p><p>带有这种心态的人去践行了一个自助概念，发现对他们没用，于是他们就到处去告诉别人那根本不管用。</p><p>而与此同时，却有另一些人对完全相同的概念深信不疑。</p><p>就拿去健身房为例。</p><p>有些人喜欢卧推，有些人则讨厌它。</p><p>有些人说它对胸肌生长来说是个糟糕的动作，另一些人却说它是最好的。</p><p>抛开力学、基因、新手红利和肌肉起止点不谈……</p><p>如果不去坚持练习，你怎么能知道卧推对你来说是不是一个好动作呢？</p><p>如果你把这个动作加入训练，不断增加重量，并坚持了 6 到 12 个月——到那时你才能决定它是好是坏。</p><p>这同样适用于任何其他能改善你生活的概念。</p><p>只试了一天，就觉得它糟透了然后放弃，这会他妈毁了你的（f*ck you up）。</p><h2 id="觉察的根基与直接经验的殿堂" tabindex="-1">觉察的根基与直接经验的殿堂 <a class="header-anchor" href="#觉察的根基与直接经验的殿堂" aria-label="Permalink to &quot;觉察的根基与直接经验的殿堂&quot;">​</a></h2><p>所有真正的自我提升都源于觉察，并通过直接经验得以巩固。</p><p>自助类信息让你<em>觉察</em>到你可能存在的问题。它为你提供了解决问题的步骤。</p><p>在特定时间内遵循这些步骤（直接经验），才是真正改善你生活的关键。</p><p>如果你已经投入了充足的时间却仍然没有看到效果，觉察力就会重新发挥作用，这个循环会继续下去。这就是持续改进。</p><p>如果你思绪混乱或焦虑不安，而一本自助书籍告诉你去冥想，你需要坚持冥想一段时间，看看它是否真的对你有帮助。如果没有帮助，那也没关系。</p><p>自助概念就像是你觉察力的“推进器”。</p><p>直接经验能帮助你了解它对你是否有用。</p><p>如果它对你有用，内在动力就会开始建立。</p><p>如果它对你没用，那就回到觉察这一步。而这正是大多数人跳过的环节。</p><p>此时你能做的最糟糕的事，就是全盘否定整个自助体系。</p><p>那就是你最终只能过平庸一生的原因。</p><p>给我找出一个你渴望成为其那样的人，看看他们的生活中是否没有持续改进的根基。你找不到的。即使你能找到，这些人也不值得你渴望去效仿。</p><p>如果你不在业务增长的同时提升自己，你的业务就会受损。</p><p>如果你不在人际关系加深的同时提升自己，你的关系就会受损。</p><p>如果你没有觉察到某些习惯正在引发隐患，你的健康就会受损。</p><h2 id="tldr-太长不看" tabindex="-1">TLDR (太长不看) <a class="header-anchor" href="#tldr-太长不看" aria-label="Permalink to &quot;TLDR (太长不看)&quot;">​</a></h2><p>如果你阅读自助内容只是为了感觉自己好像真的在做些什么，那就是糟糕的。</p><p>如果你能随着时间的推移培养出觉察力和内在驱动力，那自我提升就是有益的。</p><hr><p><a href="/en/letters/why-self-help-is-ruining-your-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',58))])}const g=t(h,[["render",d]]);export{y as __pageData,g as default};
